    """Split total (in grosze) between people as evenly as possible."""
    if people < 1:
        raise ValueError("people must be at least 1")
    share, remainder = divmod(total, people)
    # Give the leftover grosze, one each, to the first `remainder` people so the parts sum to total.
    return [share + 1 if i < remainder else share for i in range(people)]


